import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int c = in.read();
        while (c < '0' || c > '9') c = in.read();
        int n = 0;
        while (c >= '0' && c <= '9') { n = n * 10 + c - '0'; c = in.read(); }
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < n; k++) {
            while (c != -1 && c <= ' ') c = in.read();
            // Stream each word: a run of length L needs L / 2 replacements.
            long ans = 0;
            int prev = -1, run = 0;
            while (c != -1 && c > ' ') {
                if (c == prev) run++;
                else { ans += run / 2; run = 1; prev = c; }
                c = in.read();
            }
            ans += run / 2;
            sb.append(ans).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := rd.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return ""
	}
	b := []byte{}
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		b = append(b, c)
		c, err = rd.ReadByte()
	}
	return string(b)
}

func main() {
	n := readInt()
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for k := 0; k < n; k++ {
		s := readToken()
		ans := 0
		// A run of length L needs L / 2 replacements (change every second character).
		for i := 0; i < len(s); {
			j := i + 1
			for j < len(s) && s[j] == s[i] {
				j++
			}
			ans += (j - i) / 2
			i = j
		}
		w.WriteString(strconv.Itoa(ans) + "\n")
	}
}
